import {CASE_REQUIREMENTS,escapeHTML as esc} from './engine.js?v=31';
import {EXP_EDGES,edgeKey} from './expansion-engine.js?v=31';
export const PRESENTATION_KEY='qinghe.presentation.v1';
export function freshPresentation(){return {version:1,likes:[],reports:[],note:'',crossed:[],effects:true,seen:[]};}
export function parsePresentation(raw){const s=freshPresentation();try{const x=JSON.parse(raw);if(!x||x.version!==1)return s;for(const key of ['likes','reports','crossed','seen'])if(Array.isArray(x[key]))s[key]=[...new Set(x[key].filter(v=>typeof v==='string'&&v.length<100))].slice(0,150);s.note=typeof x.note==='string'?x.note.slice(0,4000):'';s.effects=x.effects!==false;return s;}catch{return s;}}
export function evidenceSlips(state,clues,archiveDocs){const confirmed=new Set(state.deduced?['post','source']:[]);for(let i=0;i<state.caseStage;i++)for(const id of CASE_REQUIREMENTS[i]||[])confirmed.add(id);if(state.caseStage>=4)confirmed.add('sameImage');const archiveConfirmed=new Set(EXP_EDGES.filter(e=>state.expansion.links.includes(edgeKey(e))).flatMap(e=>[e.from,e.to]));return [...state.clues.filter(id=>Object.hasOwn(clues,id)).map(id=>({id:'case:'+id,title:clues[id].title,text:clues[id].text,route:clues[id].route,confirmed:confirmed.has(id)})),...state.expansion.evidence.filter(id=>Object.hasOwn(archiveDocs,id)).map(id=>({id:'archive:'+id,title:archiveDocs[id].title,text:archiveDocs[id].summary,route:'#archive/'+id,confirmed:archiveConfirmed.has(id)}))];}
export function shouldDelayRoute(hash,previous){if(hash===previous)return false;return ['chat','chats','accounts','locker','folder','staff-login','recover','mailbox','vault'].includes(String(hash).slice(1).split('/')[0]);}
export function shouldRevealWithdrawal(state,id){return ['withdrawal','deleted'].includes(id)||id==='quote'&&state.caseStage>=6;}
export function createImmersion({getState,clues,archiveDocs,chapters,archiveChapters,view,toast}){
 let prefs;try{prefs=parsePresentation(localStorage.getItem(PRESENTATION_KEY));}catch{prefs=freshPresentation();}
 let loadingTimer,committedHash='',pendingCommit=null,pendingHash='',drawerReturn=null,lastGlitch=-Infinity,fxTimer,typingTimer;
 const reduced=()=>globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches===true;
 const persist=()=>{try{localStorage.setItem(PRESENTATION_KEY,JSON.stringify(prefs));}catch{toast('界面标记暂时无法保存，调查进度不受影响。');}};
 const element=id=>document.getElementById(id);
 document.body.insertAdjacentHTML('beforeend',`<button class="notebook-tab" data-notes-toggle aria-controls="clueDrawer" aria-expanded="false"><span aria-hidden="true">▤</span> 线索便签 <b data-slip-count>0</b></button><nav class="mobile-quick" aria-label="调查快捷操作"><a href="#directory"><span aria-hidden="true">☷</span> 快速返回目录</a><button data-notes-toggle aria-controls="clueDrawer" aria-expanded="false"><span aria-hidden="true">▤</span> 线索便签 <b data-slip-count>0</b></button></nav><dialog id="clueDrawer" class="clue-drawer" aria-labelledby="clueDrawerTitle"><header class="notebook-header"><div><small>高三 / 随堂记录</small><h2 id="clueDrawerTitle">by 的线索本</h2></div><button data-close-notes aria-label="合上线索本">×</button></header><div class="notebook-inside" id="notebookInside"></div></dialog><dialog id="forumReport" class="forum-report-dialog" aria-labelledby="forumReportTitle"><div class="dialog-header"><span id="forumReportTitle">向版主举报</span><button data-close-forum-report aria-label="关闭举报窗口">×</button></div><form id="forumReportForm"><p>请选择举报原因：</p><label><input type="radio" name="reason" value="rumour" required> 未经核实的信息</label><label><input type="radio" name="reason" value="privacy"> 涉及他人隐私</label><label><input type="radio" name="reason" value="other"> 其他</label><p class="bbs-offline-note">当前为论坛存档副本，操作只在此副本内标记。</p><button class="primary" type="submit">标记这条举报</button><p id="reportReceipt" role="status"></p></form></dialog>`);
 element('appWindow').insertAdjacentHTML('beforeend','<div id="intranetLoading" class="intranet-loading" hidden role="status" aria-live="polite"><span class="intranet-spinner" aria-hidden="true"></span><span>正在连接青禾内网服务器...</span></div><div id="scanlineFx" class="scanline-fx" hidden aria-hidden="true"></div><div id="connectionNotice" class="connection-notice" hidden role="status">连接已恢复</div>');
 function floorActions(key){return `<footer class="bbs-floor-footer"><div class="bbs-post-controls"><button data-floor-like="${esc(key)}" aria-pressed="${prefs.likes.includes(key)}">${prefs.likes.includes(key)?'已赞':'点赞'} <b>${prefs.likes.includes(key)?1:0}</b></button><button data-floor-report="${esc(key)}">${prefs.reports.includes(key)?'已标记举报':'举报'}</button></div><span>IP 属地：校内 <i>|</i> 来自 青禾校园网客户端</span></footer>`;}
 function drawNotebook(){const slips=evidenceSlips(getState(),clues,archiveDocs);element('notebookInside').innerHTML=`<p class="notebook-owner">仅自己可见 · 已收 ${slips.length} 条<br><span class="pen-crossout">先找谁最可疑</span>　先对材料</p><div class="notebook-legend"><i></i> 黄色便签：已在推理中核对</div>${slips.length?`<div class="sticky-stack">${[...slips].reverse().map((s,i)=>`<article class="sticky-slip ${s.confirmed?'confirmed':''} ${prefs.crossed.includes(s.id)?'crossed':''}" style="--slip-angle:${[.5,-.7,.3,-.4][i%4]}deg"><small>${s.confirmed?'✓ 已核对':'待核对'} / ${String(slips.length-i).padStart(2,'0')}</small><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p><footer><a href="${s.route}" data-slip-link>翻原材料 ↗</a><button data-cross-slip="${s.id}" aria-pressed="${prefs.crossed.includes(s.id)}">${prefs.crossed.includes(s.id)?'取消划线':'铅笔划线'}</button></footer></article>`).join('')}</div>`:'<div class="notebook-empty">本子还是空的。<br>读到有用的材料，点“记入笔记”或“保存副本”。</div>'}<form id="personalNoteForm"><label for="personalNote">随手记两句</label><textarea id="personalNote" name="note" rows="4" maxlength="4000" placeholder="这里写的内容仅保存在这台电脑上。">${esc(prefs.note)}</textarea><button class="secondary" type="submit">保存手记</button><span id="personalNoteStatus" role="status"></span></form><a class="notebook-board-link" href="${getState().caseSolved?'#board':'#notes'}" data-slip-link>展开调查笔记 / 证据关系 →</a><details class="notebook-settings"><summary>界面设置</summary><label><input type="checkbox" data-immersion-effects ${prefs.effects?'checked':''}> 内网连接等待与氛围动效</label><p>系统开启“减少动态效果”时，不播放模糊、抖动或扫描线。</p></details>`;}
 function sync(){const n=getState().clues.length+getState().expansion.evidence.length;document.querySelectorAll('[data-slip-count]').forEach(e=>e.textContent=n);}
 function openNotebook(){drawNotebook();drawerReturn=document.activeElement;const d=element('clueDrawer');if(!d.open)d.showModal();document.querySelectorAll('[data-notes-toggle]').forEach(b=>b.setAttribute('aria-expanded','true'));}
 function closeNotebook(){const d=element('clueDrawer'),draft=element('personalNote');if(d.open&&typeof draft?.value==='string'){prefs.note=draft.value.slice(0,4000);persist();}if(d.open)d.close();document.querySelectorAll('[data-notes-toggle]').forEach(b=>b.setAttribute('aria-expanded','false'));if(drawerReturn?.isConnected)drawerReturn.focus({preventScroll:true});}
 function cancelLoading(){clearTimeout(loadingTimer);pendingCommit=null;pendingHash='';element('intranetLoading').hidden=true;view.inert=false;view.removeAttribute('aria-busy');}
 function navigate(hash,commit,entered){cancelLoading();clearInterval(typingTimer);if(!entered||!prefs.effects||!shouldDelayRoute(hash,committedHash)){committedHash=hash;return false;}pendingCommit=commit;pendingHash=hash;view.inert=true;view.setAttribute('aria-busy','true');element('intranetLoading').hidden=false;loadingTimer=setTimeout(()=>{if((location.hash||'#forum')!==hash){cancelLoading();return;}cancelLoading();committedHash=hash;commit();},300);return true;}
 function glitch(key){if(!prefs.effects||reduced()||prefs.seen.includes(key)||performance.now()-lastGlitch<30000)return;lastGlitch=performance.now();prefs.seen.push(key);prefs.seen=prefs.seen.slice(-100);persist();const scan=element('scanlineFx'),notice=element('connectionNotice');scan.hidden=false;scan.classList.remove('is-active');void scan.offsetWidth;scan.classList.add('is-active');setTimeout(()=>{scan.hidden=true;},100);notice.hidden=false;clearTimeout(fxTimer);fxTimer=setTimeout(()=>notice.hidden=true,1200);}
 function decorate(section,id){sync();if(shouldRevealWithdrawal(getState(),id)&&section==='casefile'){const content=document.querySelector('#readerBody .case-document');if(content){content.classList.toggle('withdrawal-recovery',prefs.effects&&!reduced());content.insertAdjacentHTML('afterbegin',`<p class="withdrawal-label">${id==='deleted'?'（原文件已删除，以下是对方保留的私信副本）':'（该发言已由原作者撤回，以下为先前留存的记录）'}</p>`);}}
  if(section==='directory')renderDirectory();
  if(['chat','chats'].includes(section)&&prefs.effects&&!reduced()){const bubble=[...view.querySelectorAll('.chat-line:not(.mine) .bubble')].at(-1);if(bubble){const original=bubble.textContent,characters=Array.from(original);if(characters.length){const sr=document.createElement('span'),visual=document.createElement('span');sr.className='immersion-sr';sr.textContent=original;visual.setAttribute('aria-hidden','true');bubble.replaceChildren(sr,visual);const began=performance.now(),duration=Math.min(1200,characters.length*22);typingTimer=setInterval(()=>{const count=Math.min(characters.length,Math.ceil((performance.now()-began)/duration*characters.length));visual.textContent=characters.slice(0,count).join('');if(count===characters.length)clearInterval(typingTimer);},30);}}}
 }
 function renderDirectory(){const s=getState();view.innerHTML=`<div class="bbs-breadcrumb"><a href="#forum">青禾论坛</a> » 调查目录</div><section class="case-directory"><header><small>当前已开放的记录</small><h1>调查目录</h1><button class="secondary" data-notes-toggle>翻开线索本</button></header><a href="#post/reports"><b>01—03</b><span>周测与第三份报告</span><small>论坛原帖</small></a>${s.finished?chapters.filter(c=>c.number<=s.caseStage+4).map(c=>`<a href="#chapter/${c.number}"><b>${String(c.number).padStart(2,'0')}</b><span>${c.title}</span><small>${c.number<s.caseStage+4?'已核对':'当前记录'}</small></a>`).join(''):''}${s.caseSolved?archiveChapters.filter(c=>c.number<=s.expansion.stage+13).map(c=>`<a href="#annex/${c.number}"><b>${c.number}</b><span>${c.title}</span><small>${c.number<s.expansion.stage+13?'已核对':'当前记录'}</small></a>`).join(''):''}<a href="#forum"><b>↩</b><span>返回青禾论坛</span></a></section>`;}
 document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-notes-toggle')){openNotebook();return;}if(b.hasAttribute('data-close-notes')||b.hasAttribute('data-slip-link')){closeNotebook();return;}if(b.dataset.crossSlip){const draft=element('personalNote');if(typeof draft?.value==='string')prefs.note=draft.value.slice(0,4000);const id=b.dataset.crossSlip;prefs.crossed=prefs.crossed.includes(id)?prefs.crossed.filter(v=>v!==id):[...prefs.crossed,id];persist();drawNotebook();element('notebookInside').querySelector(`[data-cross-slip="${id}"]`)?.focus({preventScroll:true});return;}if(b.dataset.floorLike){const key=b.dataset.floorLike;prefs.likes=prefs.likes.includes(key)?prefs.likes.filter(v=>v!==key):[...prefs.likes,key];persist();b.setAttribute('aria-pressed',String(prefs.likes.includes(key)));b.innerHTML=`${prefs.likes.includes(key)?'已赞':'点赞'} <b>${prefs.likes.includes(key)?1:0}</b>`;return;}if(b.dataset.floorReport){const dialog=element('forumReport');dialog.dataset.floor=b.dataset.floorReport;element('reportReceipt').textContent=prefs.reports.includes(b.dataset.floorReport)?'这条举报已在副本中标记。':'';element('forumReportForm').reset();dialog.showModal();return;}if(b.hasAttribute('data-close-forum-report'))element('forumReport').close();});
 document.addEventListener('submit',e=>{if(e.target.id==='personalNoteForm'){e.preventDefault();prefs.note=String(new FormData(e.target).get('note')||'').slice(0,4000);persist();element('personalNoteStatus').textContent=' 已保存';}if(e.target.id==='forumReportForm'){e.preventDefault();const key=element('forumReport').dataset.floor;if(!prefs.reports.includes(key))prefs.reports.push(key);persist();element('reportReceipt').textContent='已在当前副本标记，请勿重复举报。';document.querySelectorAll('[data-floor-report]').forEach(b=>{if(b.dataset.floorReport===key)b.textContent='已标记举报';});}});
 document.addEventListener('change',e=>{if(e.target.matches('[data-immersion-effects]')){prefs.effects=e.target.checked;persist();if(!prefs.effects){const commit=pendingCommit,hash=pendingHash;cancelLoading();if(commit&&(location.hash||'#forum')===hash){committedHash=hash;commit();}}}});
 document.addEventListener('keydown',e=>{if(e.altKey&&e.key.toLowerCase()==='n'){e.preventDefault();element('clueDrawer').open?closeNotebook():openNotebook();}});
 element('clueDrawer').addEventListener('cancel',e=>{e.preventDefault();closeNotebook();});
 element('clueDrawer').addEventListener('click',e=>{if(e.target!==element('clueDrawer'))return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeNotebook();});
 document.addEventListener('qinghe:evidence-confirmed',e=>{const s=getState(),step=e.detail?.step;if(e.detail?.kind==='archive'&&step>=3)glitch('archive:'+step);else if(e.detail?.kind==='case'&&step>=4)glitch('case:'+step);});
 return {floorActions,sync,navigate,decorate,reset(){closeNotebook();cancelLoading();prefs=freshPresentation();persist();},openNotebook};
}
